import{_ as e,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"风险 Risk","description":"投资中唯一需要计算的，是永久性损失的风险","frontmatter":{"title":"风险 Risk","description":"投资中唯一需要计算的，是永久性损失的风险"},"headers":[],"relativePath":"02_concepts/risk.md","filePath":"02_concepts/risk.md"}'),r={name:"02_concepts/risk.md"};function u(q,t,p,h,s,i){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="风险-risk" tabindex="-1">风险 Risk <a class="header-anchor" href="#风险-risk" aria-label="Permalink to &quot;风险 Risk&quot;">​</a></h1><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1960s</strong></td><td style="text-align:left;">风险定义——收益的不确定性</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1987年/核心总结">1987年</a></strong></td><td style="text-align:left;">股灾中的投资组合保险批判</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1993年/核心总结">1993年</a></strong></td><td style="text-align:left;">安全边际是投资成功的基石</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1997年/核心总结">1997年</a></strong></td><td style="text-align:left;">不借钱，不杠杆，跌了是机会</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2001年/核心总结">2001年</a></strong></td><td style="text-align:left;">恐怖主义风险——不可定价的风险</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2002年/核心总结">2002年</a></strong></td><td style="text-align:left;">衍生品是定时炸弹</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2003年/核心总结">2003年</a></strong></td><td style="text-align:left;">保险浮存金——免费资本，不是杠杆</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结">2008年</a></strong></td><td style="text-align:left;">恐惧与流动性危机是两回事</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2020年/核心总结">2020年</a></strong></td><td style="text-align:left;">保留资本等待机会——风险管理不是恐惧</td></tr></tbody></table><hr><h2 id="按十年划分的核心观点" tabindex="-1">按十年划分的核心观点 <a class="header-anchor" href="#按十年划分的核心观点" aria-label="Permalink to &quot;按十年划分的核心观点&quot;">​</a></h2><h3 id="_1960年代-风险的本质定义" tabindex="-1">1960年代：风险的本质定义 <a class="header-anchor" href="#_1960年代-风险的本质定义" aria-label="Permalink to &quot;1960年代：风险的本质定义&quot;">​</a></h3><p>1960年代是巴菲特合伙基金时期，他开始系统性地思考风险的真正含义。与当时学术界用&quot;波动率&quot;定义风险的思路截然不同，巴菲特将风险锚定在收益的不确定性上：</p><blockquote><p>&quot;风险是收益的不确定性，不确定性越大，风险越高。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1960年代合伙基金时期</p></blockquote><p>这一时期的核心洞察是：风险不等于股价波动，而是<strong>你实际能拿到多少回报的不确定性</strong>。一只股票可能价格波动很小，但如果未来收益高度不确定，那它的风险反而更大。这个朴素的定义奠定了他此后六十年的风险管理哲学。</p><h3 id="_1970-1980年代-从波动中获利" tabindex="-1">1970-1980年代：从波动中获利 <a class="header-anchor" href="#_1970-1980年代-从波动中获利" aria-label="Permalink to &quot;1970-1980年代：从波动中获利&quot;">​</a></h3><p>1987年股灾是现代金融史上最剧烈的单日暴跌之一，道琼斯指数一天内下跌22.6%。华尔街陷入恐慌，但巴菲特看到的是机会——更准确地说，他看到的是<strong>别人的错误</strong>给了他更好的入场价格：</p><blockquote><p>&quot;很多机构搞投资组合保险，越跌越自动卖，这种行为给真正投资者更好机会。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1987年致股东信</p></blockquote><p>所谓&quot;投资组合保险&quot;是当时华尔街流行的策略：设定一个止损线，股价跌到某个阈值就自动卖出，用程序化交易&quot;保护&quot;下跌风险。巴菲特的批判直指要害——当所有人都用同一策略越跌越卖时，卖出本身就制造了更多的下跌，形成恶性循环。而真正了解企业价值的投资者，反而因此获得了以更低价格买入好公司的机会。</p><h3 id="_1990年代-安全边际——投资成功的基石" tabindex="-1">1990年代：安全边际——投资成功的基石 <a class="header-anchor" href="#_1990年代-安全边际——投资成功的基石" aria-label="Permalink to &quot;1990年代：安全边际——投资成功的基石&quot;">​</a></h3><p>1993年，巴菲特在致股东信中系统阐述了安全边际的核心理念。安全边际源自格雷厄姆，但巴菲特将其从&quot;便宜买烂公司&quot;升级为&quot;用折扣买好公司&quot;：</p><blockquote><p>&quot;安全边际是投资成功的基石。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1993年致股东信</p></blockquote><p>安全边际的本质是<strong>对判断失误的保护</strong>。没有人能完美预测企业的未来，但如果你以显著低于内在价值的价格买入，即使你的判断有偏差，也有缓冲空间。这不是保守，而是理性的风险管理。</p><p>1997年，巴菲特进一步阐述了他对杠杆的独特态度——不是反对所有&quot;杠杆&quot;，而是反对<strong>借钱的杠杆</strong>：</p><blockquote><p>&quot;如果你用杠杆，不借钱，你怕什么？跌了反而有机会。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1997年致股东信</p></blockquote><p>这句话的深意在于区分了两类&quot;杠杆&quot;：借钱买股票（真正的杠杆，放大亏损、可能被强制平仓）和利用浮存金等低成本资金（本质上是融资能力的优势，而非风险放大器）。巴菲特反对的是前者，拥抱的是后者。</p><h3 id="_2000年代-不可定价的风险与衍生品定时炸弹" tabindex="-1">2000年代：不可定价的风险与衍生品定时炸弹 <a class="header-anchor" href="#_2000年代-不可定价的风险与衍生品定时炸弹" aria-label="Permalink to &quot;2000年代：不可定价的风险与衍生品定时炸弹&quot;">​</a></h3><p>2001年&quot;9·11&quot;事件后，巴菲特提出了一个深刻的风险分类——<strong>不可定价的风险</strong>：</p><blockquote><p>&quot;恐怖主义风险未获得任何保费，但一旦发生损失巨大——这是不可定价的风险。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2001年致股东信</p></blockquote><p>他的洞察是：保险行业的核心逻辑是收取保费、覆盖风险。但有些风险（如大规模恐怖主义攻击）发生的概率极低，一旦发生损失极大，且历史数据不足以精确定价。这类&quot;尾部风险&quot;在正常时期被忽视，却在极端时刻造成毁灭性打击。</p><p>2002年，巴菲特对金融衍生品发出了最严厉的警告：</p><blockquote><p>&quot;衍生品是定时炸弹，一个巨大薪酬从假定数字中流出的业务充满危险。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2002年致股东信</p></blockquote><p>他指出了衍生品的两个核心危险：第一，交易对手方风险——链条上任何一个环节出问题都会引发连锁反应；第二，<strong>假定数字的幻觉</strong>——很多衍生品的价值建立在模型假设上，这些假设在极端环境下完全失效，但从业者的薪酬已经从这些&quot;假定数字&quot;中提前兑现了。2008年金融危机完美验证了他的预言。</p><p>2003年，巴菲特澄清了他对&quot;杠杆&quot;的真实立场——伯克希尔用的是浮存金，不是借钱：</p><blockquote><p>&quot;我们用杠杆，不借钱——我们用保险浮存金，这是免费资本，不是杠杆。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2003年致股东信</p></blockquote><p>这句话消除了一个常见的误解。外界常批评伯克希尔也用&quot;杠杆&quot;，但巴菲特强调：浮存金是先收保费、后付赔款的&quot;时间差&quot;资金，没有到期还款压力，没有强制平仓风险，成本极低甚至为负——这和&quot;借钱买股票&quot;有本质区别。</p><h3 id="_2010年代-长期视角下的风险管理" tabindex="-1">2010年代：长期视角下的风险管理 <a class="header-anchor" href="#_2010年代-长期视角下的风险管理" aria-label="Permalink to &quot;2010年代：长期视角下的风险管理&quot;">​</a></h3><p>2010年代，巴菲特的风险哲学进一步深化。他在2015年提出了系统性风险的警示：</p><blockquote><p>&quot;大规模破坏性攻击——网络、生物、核或化学攻击——一年内概率小，长期接近确定。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2015年致股东信</p></blockquote><p>2017年，他用伯克希尔股价的四个大跌时刻（跌幅37%-59%）论证杠杆的致命性：</p><blockquote><p>&quot;过去53年，伯克希尔股价有4次大跌。借钱买股票的人，在这种下跌中会被彻底清盘。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2017年致股东信</p></blockquote><h3 id="_2020年代-保留资本-等待机会" tabindex="-1">2020年代：保留资本，等待机会 <a class="header-anchor" href="#_2020年代-保留资本-等待机会" aria-label="Permalink to &quot;2020年代：保留资本，等待机会&quot;">​</a></h3><p>2020年新冠疫情引发全球市场暴跌，巴菲特手握超过1300亿美元现金。他没有急于抄底，而是选择等待：</p><blockquote><p>&quot;保留资本不过度操作，等待机会——这是风险管理，不是恐惧。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2020年致股东信</p></blockquote><p>2024年，他以更凝练的方式总结了这一原则：</p><blockquote><p>&quot;我们永远不会依赖陌生人的善意。&#39;大到不能倒&#39;不是伯克希尔的退路。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2024年致股东信</p></blockquote><hr><h2 id="重新定义风险" tabindex="-1">重新定义风险 <a class="header-anchor" href="#重新定义风险" aria-label="Permalink to &quot;重新定义风险&quot;">​</a></h2><p>在华尔街，风险通常被定义为&quot;波动性&quot;。<a href="/04_people/沃伦·巴菲特">巴菲特</a>对此嗤之以鼻，他认为这是对风险最普遍的误解。</p><blockquote><p>&quot;我们不认为 Beta 是风险的代名词。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2007年致股东信</p></blockquote><p>真正的风险只有一种：<strong>永久性损失本金的可能性</strong>。</p><blockquote><p>&quot;风险是你投资的公司可能在十年内倒闭或严重损害你的永久购买力。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2003年<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>年度股东大会</p></blockquote><h2 id="两个层次的风险" tabindex="-1">两个层次的风险 <a class="header-anchor" href="#两个层次的风险" aria-label="Permalink to &quot;两个层次的风险&quot;">​</a></h2><h3 id="_1-永久性损失的风险-核心风险" tabindex="-1">1. 永久性损失的风险（核心风险） <a class="header-anchor" href="#_1-永久性损失的风险-核心风险" aria-label="Permalink to &quot;1. 永久性损失的风险（核心风险）&quot;">​</a></h3><p>这是<a href="/04_people/沃伦·巴菲特">巴菲特</a>最在意的风险。一个企业可能因为竞争失败、行业衰退或管理层失误而走向消亡。一旦发生，投资本金将永久性损失。</p><blockquote><p>&quot;你必须记住，股票市场是一个躁郁症患者，他每天都会给你报价。在大部分时间里，他都会给你一个疯狂的价格——要么太高，要么太低。而真正成功的人，是那些利用他的疯狂，而不是被他牵着鼻子走的人。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><h3 id="_2-暂时性损失的风险-可接受风险" tabindex="-1">2. 暂时性损失的风险（可接受风险） <a class="header-anchor" href="#_2-暂时性损失的风险-可接受风险" aria-label="Permalink to &quot;2. 暂时性损失的风险（可接受风险）&quot;">​</a></h3><p>市场价格会因为各种原因剧烈波动——经济衰退、政策变化、情绪恐慌。这种波动带来的损失是暂时的，不是真正的风险。</p><blockquote><p>&quot;如果市场某天关闭几年，我们根本不在乎。我们持有的股票价格可能会下跌50%甚至更多。但对我们来说，如果公司本身的基本面没有变化，那只是市场在胡说八道。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2010年</p></blockquote><h2 id="巴菲特如何衡量风险" tabindex="-1">巴菲特如何衡量风险 <a class="header-anchor" href="#巴菲特如何衡量风险" aria-label="Permalink to &quot;巴菲特如何衡量风险&quot;">​</a></h2><h3 id="安全边际" tabindex="-1">安全边际 <a class="header-anchor" href="#安全边际" aria-label="Permalink to &quot;安全边际&quot;">​</a></h3><p>安全边际是<a href="/04_people/本·格雷厄姆">格雷厄姆</a>传给<a href="/04_people/沃伦·巴菲特">巴菲特</a>最重要的投资原则之一，也是他管理风险的核心工具。</p><blockquote><p>&quot;建造一座能承受30吨压力的桥梁，而不是只建一座15吨的。内在价值与价格之间的差异就是你的安全边际。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1997年</p></blockquote><p>安全边际意味着你永远不要为一个&quot;合理&quot;的价格付账——你要等待一个&quot;有吸引力&quot;的价格。这个折扣就是你面对不确定性的保护垫。</p><blockquote><p>&quot;用合理的价格购买优秀的企业，而不是用优秀的价格购买合理的企业。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><h3 id="四种永远不会投资的情况" tabindex="-1">四种永远不会投资的情况 <a class="header-anchor" href="#四种永远不会投资的情况" aria-label="Permalink to &quot;四种永远不会投资的情况&quot;">​</a></h3><blockquote><p>&quot;有四种情况我们是绝对不会投资的：第一，我们不理解的业务；第二，没有持久竞争优势的业务；第三，面临剧烈且不可预测的竞争格局的业务；第四，面临严重通货膨胀压力的业务。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><h3 id="集中投资-vs-分散投资" tabindex="-1">集中投资 vs. 分散投资 <a class="header-anchor" href="#集中投资-vs-分散投资" aria-label="Permalink to &quot;集中投资 vs. 分散投资&quot;">​</a></h3><blockquote><p>&quot;如果你知道自己在做什么，分散投资只会降低你的回报，而不是降低你的风险。说分散投资可以降低风险的人，通常是在说&#39;我不懂自己在做什么&#39;。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><p>但他也承认前提是&quot;真正懂&quot;：</p><blockquote><p>&quot;如果你没有信心对十家企业中的任何一家做出判断，那就不要把你的鸡蛋放在一个篮子里。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><h2 id="杠杆是风险的放大器" tabindex="-1">杠杆是风险的放大器 <a class="header-anchor" href="#杠杆是风险的放大器" aria-label="Permalink to &quot;杠杆是风险的放大器&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>最不原谅的风险来源是借钱投资——这是与传统&quot;杠杆&quot;的根本区别：</p><blockquote><p>&quot;用借来的钱进行投资的人，在市场下跌时会遭受双重打击。他们不仅会因为投资本身而亏损，还会因为杠杆效应而放大损失。而且，他们借款的能力会在最糟糕的时刻消失。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2019年致股东信</p></blockquote><blockquote><p>&quot;我见过很多聪明人因为杠杆而毁灭。如果你是聪明人，你不需要杠杆；如果你是傻瓜，杠杆只会让你更蠢。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><p>但他同时澄清：伯克希尔利用保险浮存金并非传统意义上的杠杆——浮存金没有到期还款压力，成本极低甚至为负，这是保险业务的内在优势，而非风险放大器。</p><h2 id="风险管理的核心原则" tabindex="-1">风险管理的核心原则 <a class="header-anchor" href="#风险管理的核心原则" aria-label="Permalink to &quot;风险管理的核心原则&quot;">​</a></h2><h3 id="_1-永远不要亏损" tabindex="-1">1. 永远不要亏损 <a class="header-anchor" href="#_1-永远不要亏损" aria-label="Permalink to &quot;1. 永远不要亏损&quot;">​</a></h3><blockquote><p>&quot;第一条规则：永远不要亏损。第二条规则：永远不要忘记第一条。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><p>真正含义是：<strong>不要冒永久性损失的风险去追求超额收益</strong>。</p><h3 id="_2-用长期视角看风险" tabindex="-1">2. 用长期视角看风险 <a class="header-anchor" href="#_2-用长期视角看风险" aria-label="Permalink to &quot;2. 用长期视角看风险&quot;">​</a></h3><blockquote><p>&quot;如果你不打算持有这只股票十年，那就不要考虑持有它十分钟。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><p>以十年为单位思考时，市场的短期波动几乎可以忽略不计，很多&quot;风险&quot;会在时间的长河中自动消解。</p><h3 id="_3-保持充足的流动性" tabindex="-1">3. 保持充足的流动性 <a class="header-anchor" href="#_3-保持充足的流动性" aria-label="Permalink to &quot;3. 保持充足的流动性&quot;">​</a></h3><blockquote><p>&quot;现金是为王的企业环境中最重要的资产之一。尽管现金没有产生任何回报，但在最坏的环境中，它保护了我们的资产负债表。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2020年致股东信</p></blockquote><p><a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>在2020年疫情期间持有超过1300亿美元的现金和国债，这让他在最需要投资的时候拥有充足的&quot;弹药&quot;。</p><h3 id="_4-远离复杂的金融衍生品" tabindex="-1">4. 远离复杂的金融衍生品 <a class="header-anchor" href="#_4-远离复杂的金融衍生品" aria-label="Permalink to &quot;4. 远离复杂的金融衍生品&quot;">​</a></h3><blockquote><p>&quot;衍生品是大规模杀伤性金融武器，具有潜在的致命危险。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2008年致股东信</p></blockquote><blockquote><p>&quot;衍生品是定时炸弹，一个巨大薪酬从假定数字中流出的业务充满危险。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2002年致股东信</p></blockquote><h2 id="对普通投资者的启示" tabindex="-1">对普通投资者的启示 <a class="header-anchor" href="#对普通投资者的启示" aria-label="Permalink to &quot;对普通投资者的启示&quot;">​</a></h2><ol><li><strong>把风险定义为永久性损失</strong>——不要被短期波动吓倒，也不要用波动率来衡量风险</li><li><strong>始终留有安全边际</strong>——不要为任何资产付出过高的价格</li><li><strong>远离借钱杠杆</strong>——时间是你的朋友，借款是你的敌人</li><li><strong>保持现金储备</strong>——在别人恐惧时有子弹可用</li><li><strong>长期思维</strong>——以十年为单位思考，大幅降低风险感知</li></ol><blockquote><p>&quot;风险来自于不知道自己在做什么。&quot; ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a></p></blockquote><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>的风险哲学可以归结为一句话：<strong>控制永久性损失的风险，让时间去积累复利。</strong></p><p>他通过安全边际、优质企业、集中投资和远离杠杆这四把钥匙，构建了一套完整的风险管理框架。这套框架不是为了避免所有波动，而是为了在漫长的投资生涯中，<strong>永远不被市场淘汰</strong>。</p><blockquote><p>&quot;活得够久&quot;才是投资中最重要的风险管理。 ——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>的实践真谛</p></blockquote><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=核心总结">1987年：核心总结</a> → <a href="/01_letters/1987年/翻译">/01_letters/1987年/翻译</a></li><li><a href="/search?q=核心总结">1993年：核心总结</a> → <a href="/01_letters/1993年/翻译">/01_letters/1993年/翻译</a></li><li><a href="/search?q=核心总结">2002年：核心总结</a> → <a href="/01_letters/2002年/翻译">/01_letters/2002年/翻译</a></li><li><a href="/search?q=核心总结">2008年：核心总结</a> → <a href="/01_letters/2008年/翻译">/01_letters/2008年/翻译</a></li><li><a href="/search?q=核心总结">2020年：核心总结</a> → <a href="/01_letters/2020年/翻译">/01_letters/2020年/翻译</a></li></ul>',94)])])}const d=e(r,[["render",u]]);export{c as __pageData,d as default};
